const e="Thesis Policy",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/engineering/academic-policies-procedures/thesis-policy/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/engineering/academic-policies-procedures/thesis-policy/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:1,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"1 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"2026-2027 Edition",sh:4}}],overflow:0}]}},s=0,o=2027,i=[{type:"SECTION",title:"2026-2027 Edition",creditsRequired:4,minRequirementCount:1,requirements:[],notes:["This policy applies to all full-time and part-time graduate students pursuing a master's degree program or students in the PlusOne accelerated master’s degree program in the College of Engineering.","Students that pursue the thesis option in a master’s degree will enroll in 4 semester hours of Master’s Project followed by 4 semester hours of Thesis, unless otherwise stated by the program’s requirements.","If a student is unable to complete the thesis requirements after registering for the Thesis course (7990), they should consult their academic advisor to determine the appropriate course for the following term to maintain their registration status while completing the thesis requirements.","In addition to completing the Master’s Project and Thesis courses, students must successfully complete the thesis submission process by the specified deadlines, including securing committee and Graduate School of Engineering signatures and submission of an electronic copy of their MS thesis to ProQuest.","Students pursuing the thesis option may switch to a Master's Project or coursework-only option if available at their campus after completing the Master's Project course. If a student changes from the thesis option to Master’s Project, no action is needed. If a student changes from the thesis option to coursework option, they may petition to count up to 4 semester hours of Master's Project as elective credit toward the coursework option. This petition will be reviewed by the program contact, who may verify the work with the thesis advisor. If the program determines that the Master's Project semester hours cannot count toward the new coursework option requirements, students may need to take additional courses at their own expense to meet the degree requirements."]}],r={name:e,metadata:t,totalCreditsRequired:s,yearVersion:o,requirementSections:i};export{r as default,t as metadata,e as name,i as requirementSections,s as totalCreditsRequired,o as yearVersion};
